head.script:

	scwin.onpageload = function() {

	};

	scwin.onpageunload = function() {

	};


	scwin.trigger1_onclick = function(e) {
		var options = {};
		options.processMsg = "다운로드중입니다..";
		options.bodyColor = "#FFFFFF";
		options.fileName = "excel.xlsx";
		options.sheetName = "sheet";
		options.type = "0";
		options.headerColor = "#0000FF";
		options.headerFontColor = "white"
		options.headerFontBold = "true";

		gridView1.advancedExcelDownload(options);


	};

	scwin.trigger2_onclick = function(e) {
		var options = {};
		options.processMsg = "다운로드중입니다..";
		options.bodyColor = "#FFFFFF";
		options.fileName = "excel.xlsx";
		options.sheetName = "sheet";
		options.type = "0";
		options.headerColor = "#0000FF";
		//options.headerFontColor = "white"
		options.headerFontColor = "#FFFFFF"
		options.headerFontBold = "true";
		options.startRowIndex = "5"

		var infoArr = [
			{rowIndex : 1, colIndex : 5, 
			rowSpan : 0, 
			colSpan : 0, 
			fontSize : "10px" , 
			text : "투자성향", 
			textAlign : "left", 
			borderColor : "#d6d6d6", 
			bgColor : "#d9e1f2", 
			"color" : "black", 
			"fontWeight" : "bold"}, 
			{rowIndex : 2, colIndex : 5, 
			rowSpan : 0, colSpan : 0, fontSize : "10px" , 
            text : "안정형='1'", textAlign : "left", 
            borderColor : "#d6d6d6", 
            bgColor : "#FFFFFF", 
            "color" : "black"},
			{rowIndex : 3, colIndex : 5, 
			rowSpan : 0, colSpan : 0, fontSize : "10px" , 
            text : "안정형='2'", textAlign : "left", 
            borderColor : "#d6d6d6", 
            bgColor : "#FFFFFF", 
            "color" : "#000000"}, //검정색
			{rowIndex : 4, colIndex : 5, 
			rowSpan : 0, colSpan : 0, fontSize : "10px" , 
            text : "안정형='3'", textAlign : "left", 
            borderColor : "#d6d6d6", 
            bgColor : "#000000", 
            "color" : "white"},//흰색
			{rowIndex : 5, colIndex : 5, 
			rowSpan : 0, colSpan : 0, fontSize : "10px" , 
            text : "안정형='4'", textAlign : "left", 
            borderColor : "#d6d6d6", 
            bgColor : "#000000", 
            "color" : "#FFFFFF"}//흰색           
        ];
		gridView1.advancedExcelDownload(options,infoArr);
	};
